import type { ArticleCore } from "../types";

export const CORES_A: Record<string, ArticleCore> = {
  epistemology: {
    lede: `[[epistemology|Epistemology]] is the study of knowledge and of the many ways knowing can fail. It asks what distinguishes a lucky true guess from a claim worth trusting, how perception and testimony feed belief, and whether skepticism is a pose or a discovery. In this vault it sits between [[empiricism|empiricism]] and [[rationalism|rationalism]], with [[hume|Hume]] and [[kant|Kant]] as the two weather systems that still organize the sky.`,
    idea: `The traditional analysis treated knowledge as justified true belief until Edmund Gettier's 1963 cases showed that the formula was too thin: a belief can be true and justified and still be a fluke. Subsequent repairs — causal theories, reliabilism, virtue epistemology, safety and sensitivity conditions — disagree about whether justification is an internal state or an external track record. Skepticism is the standing pressure. Cartesian doubt uses error as a method for finding a remainder; Pyrrhonian doubt suspends judgment without promising a remainder. [[logic|Logic]] supplies the hygiene of inference; [[perception|perception]] supplies most of the input; science, in the wake of the [[scientific-revolution|Scientific Revolution]], supplies the most successful social technology for correcting both. Social epistemology adds that much of what any person knows is borrowed, which makes testimony, institutions, and disagreement first-class objects rather than afterthoughts.`,
    lineage: `Plato's Theaetetus already treats knowledge as a problem rather than a gift. Aristotle's Posterior Analytics offers demonstration as the gold standard. Medieval debates about illumination and abstraction kept the problem theological. Early modern philosophy split the sources: Descartes and the rationalists trusted the mind's contents; Locke, Berkeley, and [[hume|Hume]] trusted, with increasing unease, the stream of impressions. Hume's fork — relations of ideas versus matters of fact — left causation and the self as habits. [[kant|Kant]] answered that the mind contributes forms of intuition and categories, so knowledge is of appearances structured by us. The twentieth century added language, probability, and social practice: the linguistic turn, Bayesian confirmation, and the sociology of science. None of these abolished the others.`,
    tension: `Two live fights dominate. Internalists hold that a knower must have access to her reasons; externalists hold that a reliable connection to the world can be enough even if she cannot recite it. The second fight is about how much epistemology should defer to [[cognitive-psychology|cognitive psychology]] and [[bayesian-brain|Bayesian]] models of the brain. Naturalists want a theory continuous with science; traditionalists warn that using science to justify science is a circle. The atlas does not close the circle. It keeps [[empiricism|empiricism]] and [[rationalism|rationalism]] as neighboring climates so a reader can feel the draft between them.`,
  },
  metaphysics: {
    lede: `[[metaphysics|Metaphysics]] is inquiry into the basic furniture of the world: what exists, what it is to exist, and how the existents hang together. Substance, property, time, causation, possibility, and identity are its recurring inventory. [[aristotle|Aristotle]] named the subject; [[kant|Kant]] put it on trial; it survived the trial by becoming more careful, not by becoming quieter.`,
    idea: `A metaphysical theory is a proposal about categories. Are there only particulars, or also universals? Are there only actual things, or also merely possible ones? Is time a river or a block? Is causation a push, a regularity, or a counterfactual dependence? [[dualism|Dualism]] is the special case in which mind is a different kind of stuff from body. [[set-theory|Set theory]] and [[spacetime|spacetime]] show that mathematics and [[physics|physics]] keep doing metaphysics under other names: they decide what the world's individuals are allowed to be. Contemporary analytic metaphysics often proceeds by possible-worlds semantics, grounding, and ontological commitment in Quine's sense — to be is to be the value of a bound variable — while process and feminist metaphysicians argue that the inventory was always political. [[consciousness|Consciousness]] remains the item that will not sit still in any inventory.`,
    lineage: `Aristotle's Metaphysics asked after being qua being. Scholasticism turned that into a system of act and potency, essence and existence. Early moderns tried to start from clear ideas: Descartes's two substances, Spinoza's one, Leibniz's many windowless monads. Hume dissolved causation into habit and the self into a bundle. Kant relocated the necessary structure of the world into the necessary structure of experience, after which "metaphysics" became a fighting word. The linguistic turn tried to replace it with the analysis of language. It returned anyway, because physics, modality, and personal identity kept generating questions that would not parse as mere grammar.`,
    tension: `The standing accusation is that metaphysics is poetry with footnotes. The standing reply is that every science smuggles a metaphysics, and it is better to smuggle in daylight. A live dispute is whether grounding and fundamentality are explanatory or merely honorific. Another is whether [[spacetime|spacetime]] as described by [[relativity|relativity]] abolishes tense and becoming. Readers who want to watch the smuggling happen should keep [[physics|physics]] and [[logic|logic]] open beside this article.`,
  },
  ethics: {
    lede: `[[ethics|Ethics]] is the theory of right action, good lives, and the reasons that bind us to one another. It is not etiquette and not the criminal law, though it is asked to justify both. In this vault it neighbors [[utilitarianism|utilitarianism]], [[political-philosophy|political philosophy]], [[decision-making|decision making]], and [[game-theory|game theory]], because a theory of the good that cannot talk to choice and conflict is a sermon.`,
    idea: `Three families still organize the classroom: consequentialism, which judges acts by outcomes; deontology, which judges by duties and rights; and virtue ethics, which judges by the kind of person an act expresses. [[aristotle|Aristotle]]'s Nicomachean Ethics is the ancestor of the third; [[kant|Kant]]'s Groundwork of the second; Bentham and Mill of the first, filed here as [[utilitarianism|utilitarianism]]. Applied ethics — bioethics, climate, war, AI — is where the families stop being diagrams and start costing lives. Metaethics asks whether moral claims are true in the way that "snow is white" is true, or whether they express attitudes, prescriptions, or cultural software. Evolutionary and psychological accounts, via [[decision-making|decision making]] and [[social-psychology|social psychology]], explain why we have the intuitions we have without yet saying whether we should keep them.`,
    lineage: `Greek eudaimonia, Confucian ritual, Buddhist non-harm, and Abrahamic command ethics are older than the modern word. Early modern natural law and the Scottish sentimentalists made morality a fact about human nature. Kant made it a fact about reason. Utilitarians made it a fact about pleasure and pain that could be counted. Nietzsche diagnosed the counting as a slave revolt; Rawls, in the twentieth century, tried to rebuild justice as fairness without a full theory of the good. Feminist care ethics and animal ethics widened the circle of who counts. The lineage is not a progress bar. It is a set of tools that still cut.`,
    tension: `Moral luck, demandingness, and the conflict between partiality and impartiality are not puzzles at the edge. They are the subject. A theory that cannot tell you whether to save a stranger or your child has not yet started. [[free-will|Free will]] threatens responsibility if determinism is true; neuroscience is sometimes recruited as a witness. Political life threatens personal ethics with dirty hands. The atlas keeps [[political-philosophy|political philosophy]] adjacent so that the personal and the public cannot pretend to be strangers.`,
  },
  logic: {
    lede: `[[logic|Logic]] is the science of valid inference: which conclusions have to be true if the premises are. From [[aristotle|Aristotle]]'s syllogistic to Frege's Begriffsschrift to [[godel|Gödel]]'s incompleteness theorems, it has been both a hygiene for the rest of philosophy and a branch of [[mathematics|mathematics]] that grew into [[computation-theory|computation theory]].`,
    idea: `A logic specifies a language, a notion of interpretation, and a consequence relation. Classical first-order logic is the default: bivalent, extensional, compact, complete. Modal logics add necessity; intuitionistic logics drop excluded middle; relevant and paraconsistent logics police the paradoxes of material implication and explosion. Proof theory studies derivations; model theory studies structures; computability theory, after [[turing|Turing]], studies what a finite procedure can decide. [[proof|Proof]] is the social technology that makes a derivation public. [[set-theory|Set theory]] is the usual background ontology. The philosophical payload is that validity is not psychology. A bad argument can feel great.`,
    lineage: `Aristotle's Organon, Stoic propositional logic, medieval supposition theory, then a long drought until Leibniz's dream of a calculus ratiocinator. Boole algebraized AND and OR; Frege quantified; Russell and Whitehead tried to build mathematics on the result; Gödel showed that any sufficiently rich formal system cannot prove all its truths and cannot prove its own consistency (if it is consistent). Turing recast undecidability as a machine that does not halt. The lineage then splits into analytic philosophy's housekeeping and computer science's operating system.`,
    tension: `Which logic is the One True Logic, or is that a bad question? Classicists treat rivals as useful tools; pluralists treat classical logic as one tool among others. Gödel and Turing jointly imply that some well-posed mathematical questions have no mechanical answer, which is a limit on [[epistemology|epistemology]] as much as on machines. Paradoxes — liar, sorites, Russell — remain the places where the hygiene fails in public.`,
  },
  consciousness: {
    lede: `[[consciousness|Consciousness]] is the fact of felt experience, and the puzzle of how a physical universe includes a point of view. [[qualia|Qualia]], [[dualism|dualism]], [[neuroscience|neuroscience]], and [[attention|attention]] all pull on this node. It is the scandal at the border of [[mind|mind]] and [[philosophy|philosophy]].`,
    idea: `There is something it is like to see blue, to hurt, to linger on a memory. That "something it is like," in Thomas Nagel's phrase, is what functional descriptions of [[perception|perception]] and [[working-memory|working memory]] seem to leave out. Theories proliferate: global workspace, higher-order thought, integrated information, predictive processing in the [[bayesian-brain|Bayesian brain]], panpsychism, illusionism. [[phenomenology|Phenomenology]] tries to describe the experience before the theory. [[wittgenstein|Wittgenstein]] warned that the grammar of "I see" already misleads. Meanwhile the lab maps correlates: binocular rivalry, anesthesia, blindsight, split brains. Correlates are not yet identities. [[free-will|Free will]] and moral status hang on how the identity claim goes.`,
    lineage: `The soul was a substance. Locke made consciousness the criterion of personal identity. [[james|William James]] described a stream. Behaviorism banned the stream from science; the cognitive revolution let it back in as data. Nagel, Jackson's Mary, and Chalmers's "hard problem" reopened the metaphysics in the 1970s–90s. Imaging and perturbation techniques then made consciousness an experimental variable without settling the metaphysics. The lineage is a series of permissions to talk about experience, each followed by a method that hoped to stop the talking.`,
    tension: `Illusionists say the hard problem is a trick of introspection. Dualists say the trick is the illusionism. Physicalists of various stripes try to identify experience with a function, a process, or an information pattern. None of these positions currently commands the room. Until one does, this node will keep stealing edges from [[neuroscience|neuroscience]], [[qualia|qualia]], and [[attention|attention]].`,
  },
  "political-philosophy": {
    lede: `[[political-philosophy|Political philosophy]] asks what political authority is, when it is legitimate, and how collective life should be arranged. [[plato|Plato]]'s Republic, social contract theory, and the [[enlightenment|Enlightenment]] still structure the arguments; [[democracy|democracy]] and [[capitalism|capitalism]] are the living experiments.`,
    idea: `The core problems are justification, justice, and power. Why should anyone obey? What does each person owe each other person through institutions? Who gets to decide, and how is domination disguised as consent? Liberal traditions emphasize rights, limited government, and the rule of law; civic republican traditions emphasize non-domination and public virtue; socialist traditions emphasize ownership of the means of production; anarchist traditions treat the state as a problem rather than a solution. [[ethics|Ethics]] supplies the moral vocabulary; [[social-psychology|social psychology]] supplies the facts about conformity and identity; [[game-theory|game theory]] supplies models of cooperation and defection. Rawls's original position, Nozick's side constraints, and feminist critiques of the public/private split are late chapters, not the book.`,
    lineage: `Plato's philosopher-kings and Aristotle's zoon politikon; medieval two-swords theories; Hobbes's Leviathan as an answer to civil war; Locke's property and consent; Rousseau's general will; the Federalist Papers as applied theory. Marx inverted Hegel and made class the engine. The twentieth century added totalitarianism as a data point that theory had to survive. Decolonial and critical race theorists argued that the [[enlightenment|Enlightenment]]'s universalism was a local costume. The lineage is a fight about who is in the "we."`,
    tension: `Ideal theory versus non-ideal theory: should we first describe a just society, or first describe domination as it is? Global justice versus the bounded demos. The authority of experts versus the authority of the people. A knowledge atlas is not neutral here. Maps of knowledge have always been instruments of rule — see the [[library-of-alexandria|Library of Alexandria]] and the [[printing-press|printing press]]. This cluster's job is to keep that fact visible.`,
  },
  plato: {
    lede: `[[plato|Plato]] (c. 427–347 BCE) wrote dialogues that still set the agenda for [[metaphysics|metaphysics]], [[political-philosophy|political philosophy]], and the soul. He founded the Academy in Athens and made Socrates a character whose questions outlived the city that killed him.`,
    idea: `The theory of Forms holds that particulars participate in eternal, intelligible archetypes — Justice, Beauty, the Good — which are more real than the changing things we see. The Republic braids psychology, politics, and education: justice in the city is each part doing its work, and the soul has an analogous constitution. The cave allegory is [[epistemology|epistemology]] as liberation. Later dialogues (Sophist, Parmenides, Timaeus) complicate the early theory and invent problems of not-being, participation, and cosmology. Plato is not a doctrine. He is a method of writing that refuses to die into a textbook.`,
    lineage: `A student of Socrates and teacher of [[aristotle|Aristotle]], Plato stands at the hinge of the [[axial-age|Axial Age]] in Greece. His unwritten doctrines, reported by Aristotle, and the Seventh Letter's caution about writing, suggest he trusted conversation more than the page. Neoplatonism carried him into late antiquity and Islam; the [[renaissance|Renaissance]] carried him into Florence; Whitehead's remark that European philosophy is a series of footnotes is an exaggeration that keeps being useful.`,
    tension: `Is the Republic a utopia, a satire, or a psychology? Are the Forms a theory or a ladder to be kicked away? Karl Popper made Plato an enemy of the open society; Straussians made him a writer of secrets. The atlas files him as a neighbor of [[political-philosophy|political philosophy]] and [[metaphysics|metaphysics]], not as a mascot.`,
  },
  aristotle: {
    lede: `[[aristotle|Aristotle]] (384–322 BCE) systematized [[logic|logic]], [[biology|biology]], [[ethics|Ethics]], and the categories of being. Where his teacher [[plato|Plato]] climbed toward Forms, Aristotle stayed with substances in a world that could be collected, classified, and explained by causes.`,
    idea: `A substance is a this-such, a composite of matter and form. Four causes — material, formal, efficient, final — explain change. The Organon made syllogistic the first [[logic|logic]] worth the name. The Nicomachean Ethics treats virtue as a mean, habituation as education, and eudaimonia as an activity of the soul in accordance with excellence. The Politics treats humans as political animals. The biological works are not folklore; they are the start of comparative anatomy in the West. Metaphysics, as he practices it, is the science of being qua being.`,
    lineage: `A Macedonian who studied in the Academy, tutored Alexander, and founded the Lyceum, Aristotle was lost and found several times: in late antiquity, in Arabic commentary, in the Latin thirteenth century, in Paduan science. Scholasticism is in large part Aristotle with a church. The [[scientific-revolution|Scientific Revolution]] defined itself against his physics while keeping his logic. He remains in [[biology|biology]] as a reminder that function and form were empirical topics before they were slogans.`,
    tension: `Final causes embarrass moderns and still sneak back as functions in [[biology|biology]]. The mean can look like bland moderation. His exclusions — women, slaves, barbarians — are not side notes; they structure the politics. Read him as a system that works, then watch where it should not.`,
  },
  kant: {
    lede: `[[kant|Immanuel Kant]] (1724–1804) relocated the conditions of knowledge into the structure of mind and tried to put [[metaphysics|metaphysics]] on the secure path of a science. The Critiques remain the operating system of much later [[philosophy|philosophy]], and of the [[enlightenment|Enlightenment]]'s self-image.`,
    idea: `The Critique of Pure Reason argues that space and time are forms of intuition, and that categories such as causality are rules the understanding brings to experience. We know appearances, not things in themselves. Synthetic a priori knowledge is possible because we know what we have put there. The Groundwork and second Critique locate morality in the categorical imperative: act only on maxims you could will as universal law, and treat humanity as an end. The third Critique tries to braid nature and freedom through judgment, beauty, and purpose. [[hume|Hume]], Kant said, woke him from dogmatic slumber; the waking produced a system.`,
    lineage: `A Königsberg professor who rarely traveled, Kant fused rationalist form with empiricist content. German idealism (Fichte, Schelling, Hegel) radicalized him; neo-Kantians professionalized him; analytic philosophy translated him into arguments about concepts and experience; Rawls borrowed the form of a moral law for [[political-philosophy|political philosophy]]. He is the reason "critique" still means something more than complaint.`,
    tension: `The thing in itself is a door that may open onto nonsense. The moral law's formalism is accused of emptiness, its rigorism of cruelty. Race and sex in the anthropology are not excusable as "of the time" if the time is the claimed universal. The live research program is to keep the Copernican turn without the worst of the inventory.`,
  },
  hume: {
    lede: `[[hume|David Hume]] (1711–1776) unmasked causation, the self, and morality as habits of mind. The great [[empiricism|empiricist]] of the Scottish [[enlightenment|Enlightenment]], he wrote as if philosophy should be able to survive a decent dinner.`,
    idea: `All ideas derive from impressions. Relations of ideas are demonstrative; matters of fact are probable and rest on custom. We never perceive a necessary connection between cause and effect, only constant conjunction plus a feeling of expectation. The self is a bundle of perceptions. Morality is founded on sentiment, not on reason alone, which is and ought only to be the slave of the passions. Miracles are always less probable than the testimony's corruption. These are not parlor tricks. They are a program for [[epistemology|epistemology]] and [[ethics|Ethics]] that [[kant|Kant]] could not leave unanswered.`,
    lineage: `Locke and Berkeley minus the theology, plus a historian's appetite. The Treatise of Human Nature (1739–40) fell "dead-born"; the Enquiries and the History of England did not. Adam Smith was a friend; Rousseau a disaster; the Church a wary neighbor. Twentieth-century naturalists and cognitive scientists keep rediscovering him, often without the prose.`,
    tension: `Is Hume a skeptic or a naturalist who wanted us to stop asking for guarantees we cannot have? The "Humean" theory of laws as regularities still structures debates in [[metaphysics|metaphysics]] and [[physics|physics]]. The is/ought gap is either a discovery or a dare. Read him slowly. He is funnier than his reputation and more dangerous than the joke.`,
  },
  wittgenstein: {
    lede: `[[wittgenstein|Ludwig Wittgenstein]] (1889–1951) twice rebuilt the map of meaning: first as a logical picture of the world, then as a city of language-games. He is the reason [[language|language]] will not stay a side topic in [[logic|logic]] or [[consciousness|consciousness]].`,
    idea: `The Tractatus (1921) treats a proposition as a picture of a state of affairs; what cannot be said — ethics, the mystical — must be shown, then passed over in silence. The later Investigations treats meaning as use in a form of life. Family resemblance replaces essences; private language is diagnosed as a confusion; philosophical problems are knots to be untied, not theorems to be proved. Neither book is a theory in the usual sense. Both are therapies that keep being used as theories. [[computation-theory|Computation]] inherited the early logical atomism in one lineage; ordinary-language philosophy inherited the later city.`,
    lineage: `Austrian engineer, student of Russell, elementary-school teacher, gardener, professor at Cambridge, hospital porter in wartime. The two books sandwich a silence. Influence ran through the Vienna Circle, Oxford ordinary language, and then into [[cognitive-psychology|cognitive psychology]] and AI as a warning label.`,
    tension: `Was there one Wittgenstein or two? Is the later work quietist or radically political? Can you use "meaning is use" as a slogan without betraying it? The atlas files him on the border of [[logic|logic]] and [[language|language]] and lets the reader walk both banks.`,
  },
  empiricism: {
    lede: `[[empiricism|Empiricism]] is the thesis that experience, not innate ideas, is the wellspring of knowledge. [[hume|Hume]] is its most ruthless practitioner; the [[scientific-revolution|Scientific Revolution]] is its most successful institution.`,
    idea: `If all content comes through the senses, then claims that outrun possible experience — substantial forms, occult qualities, some theologies — are not false so much as idle. Locke's blank slate, Berkeley's idealism, Hume's bundle, and Mill's methods of induction are variants. Logical empiricism in the twentieth century tried to regiment the thesis with [[logic|logic]] and verification; Quine then attacked the two dogmas that made the regimenting look clean. [[perception|Perception]] is the obvious ally and the obvious problem: experience is theory-laden, as Hanson and Kuhn insisted. [[bayesian-brain|Bayesian]] models of the brain currently recast empiricism as prediction error minimization rather than as a bucket of impressions.`,
    lineage: `Aristotle said nothing is in the intellect that was not first in the senses; medieval empiricists kept the slogan. Bacon, Boyle, and the Royal Society made it a method. The British sequence Locke–Berkeley–Hume made it a metaphysics of mind. It remains the official epistemology of the lab even when the lab's philosophers have moved on.`,
    tension: `Nativism never went away: [[chomsky|Chomsky]] on [[language|language]], Kant on categories, contemporary evolutionary psychology. If the mind contributes structure, empiricism must become a thesis about justification rather than about origin. That slide is where [[rationalism|rationalism]] has always been waiting.`,
  },
  rationalism: {
    lede: `[[rationalism|Rationalism]] is the thesis that reason can yield knowledge independent of sensory experience. [[plato|Plato]]'s recollection, Descartes's cogito, and [[kant|Kant]]'s synthetic a priori are its landmarks; [[mathematics|mathematics]] is its favorite exhibit.`,
    idea: `Some truths seem too clean to have been copied from the world: 7 + 5 = 12, nothing is both F and not-F, perhaps the causal maxim. Rationalists treat these as the mind's contribution or as glimpses of a structure more real than sensation. Innate ideas, clear and distinct perception, and intellectual intuition are the historical tools. In a cooler idiom, rationalism is a bet on [[proof|proof]] and on models that constrain experience in advance. [[logic|Logic]] is its hygiene; [[epistemology|epistemology]] is its courtroom.`,
    lineage: `Plato, then the Stoics, then Descartes, Spinoza, Leibniz — the early modern rationalists as a textbook family that would have been surprised by the grouping. Kant tried to keep necessity without innatism of content. Chomsky's poverty-of-the-stimulus argument is a late rationalist move in [[language-acquisition|language acquisition]].`,
    tension: `The standing insult is that rationalists confuse the structure of their language with the structure of the world. The standing reply is that [[empiricism|empiricism]] cannot account for the necessity it uses. The atlas keeps both as climates, not as teams.`,
  },
  utilitarianism: {
    lede: `[[utilitarianism|Utilitarianism]] is the moral theory that right action maximizes aggregate well-being. It is the most influential consequentialism, and the one [[ethics|Ethics]] cannot stop arguing with.`,
    idea: `Count the goods — pleasure, preference satisfaction, or a richer welfare — sum them across persons, and choose the act (or rule, or motive) that yields the most. Bentham's felicific calculus, Mill's higher and lower pleasures, Sidgwick's methods, and Singer's expanding circle are the canon. Decision theory and [[game-theory|game theory]] gave it a formal dialect. Effective altruism is a recent institutional form. Objections write themselves: justice, rights, special obligations, the separateness of persons, the utility monster, demandingness. Rule-utilitarians try to buy back some of what act-utilitarians sold.`,
    lineage: `Helvétius and Beccaria, then Bentham's Introduction (1789), Mill's Utilitarianism (1861), the Cambridge school, and the twentieth-century welfare state as a half-implemented cousin. Economics absorbed the counting and sometimes forgot the ethics.`,
    tension: `Can the right be reduced to the good? If not, [[kant|Kant]] is waiting. If so, how do you measure the good without flattening a life into a number? [[decision-making|Decision making]] research complicates the picture of the chooser. The theory remains the one to beat whenever policy needs a common currency.`,
  },
  dualism: {
    lede: `[[dualism|Dualism]] is the claim that mind and body are of fundamentally different kinds. Substance dualism is Descartes's version; property dualism is the version that still has friends in the [[consciousness|consciousness]] literature.`,
    idea: `If thoughts have no size, and brains do, perhaps they are not the same thing. Descartes argued from conceivability and from the indivisibility of the mind. Princess Elisabeth asked how they interact; the pineal gland did not answer. Contemporary property dualists (sometimes Chalmers) keep the physical world closed except for the extra properties of experience — [[qualia|qualia]]. Interaction, epiphenomenalism, and parallelism are the bad options for coupling. [[neuroscience|Neuroscience]] keeps finding correlates that look like identities in progress.`,
    lineage: `Plato's soul, Christian immortalism, Descartes's Meditations, occasionalists, then a long materialist counteroffensive from Hobbes through Smart and Place's identity theory to functionalism. Dualism survives as a minority report whenever reduction feels like a trick.`,
    tension: `Causal closure of the physical is the pressure. If every physical event has a physical cause, mental extra-stuff either does no work or violates physics. Epiphenomenalism saves physics and wastes the mind. The atlas files dualism next to [[consciousness|consciousness]] as a live option, not as a museum piece.`,
  },
  "free-will": {
    lede: `[[free-will|Free will]] is the disputed capacity to have done otherwise, and the moral weight that hangs on it. [[ethics|Ethics]], [[consciousness|consciousness]], [[decision-making|decision making]], and [[neuroscience|neuroscience]] all claim a piece.`,
    idea: `Compatibilists say freedom is doing what you want without coercion, even if wants have causes. Incompatibilists say that if determinism is true, "could have done otherwise" is a lie. Libertarians (the metaphysical kind) want undetermined agency without reducing it to chance. Frankfurt cases attack the need for alternative possibilities; Strawson asks whether we could ever give up reactive attitudes. Libet-style experiments and their successors are recruited, often too quickly, as news from the lab. [[dual-process|Dual-process]] psychology complicates the picture of the chooser without settling the metaphysics.`,
    lineage: `Aristotle on the voluntary, Augustine on the will, scholastic distinctions, Hobbes and Hume as compatibilists, Kant as a transcendental libertarian, Nietzsche as a genealogist. The twentieth century made it a technical debate in [[metaphysics|metaphysics]] with a side office in criminal law.`,
    tension: `If there is no free will, what happens to praise, blame, and [[ethics|Ethics]]? Some revisionists would keep the practices and drop the metaphysics; others would reform punishment. The atlas will not pretend the science has finished the job.`,
  },
  qualia: {
    lede: `[[qualia|Qualia]] are the raw feels of experience — the redness of red, the sting of pain — that resist functional reduction. They are the ammunition of the knowledge argument and the inverted spectrum, and the embarrassment of functionalist [[consciousness|consciousness]].`,
    idea: `A quale is what remains when you have listed the causal role. Jackson's Mary knows all the physical facts about color vision and still, the story goes, learns something when she sees red. The inverted spectrum asks whether functionally identical agents could feel differently. Dennett tries to dissolve qualia as a philosopher's toy; dualists and some physicalists treat them as data. [[phenomenology|Phenomenology]] describes them without reifying them as inner objects. [[perception|Perception]] science sometimes talks of qualia, sometimes refuses the word.`,
    lineage: `The term is modern (Lewis, 1929; then C. I. Lewis; then the 1970s–90s explosion). The problem is old: Locke's inverted spectrum, the explanatory gap. Nagel and Jackson made it a set piece.`,
    tension: `Are qualia properties of experience, or is "qualia" a picture that holds us captive, as [[wittgenstein|Wittgenstein]] might say? If they are real and non-physical, [[dualism|dualism]] returns. If they are real and physical, we still lack the identity. If they are not real, introspection is a liar. Pick your cost.`,
  },
  phenomenology: {
    lede: `[[phenomenology|Phenomenology]] is a method of describing experience as it is lived, before theories overlay it. Husserl founded it; Heidegger, Merleau-Ponty, and Sartre took it into existence, body, and others. It remains the first-person counterpart to [[consciousness|consciousness]] science.`,
    idea: `Bracket the existence of the world (the epoché) and describe the structures of appearance: intentionality, temporality, embodiment, the horizon of the unseen. The lifeworld is the taken-for-granted ground of science. [[embodied-cognition|Embodied cognition]] later borrowed the body; [[perception|perception]] research borrowed the idea that we see possibilities for action, not snapshots. Phenomenology is not introspection as a look-inside. It is a disciplined description of how things show up.`,
    lineage: `Brentano's intentionality, Husserl's Logical Investigations and Ideas, Heidegger's Being and Time, Merleau-Ponty's Phenomenology of Perception. The French and German receptions diverged; analytic philosophy mostly ignored it until the consciousness boom forced a reunion of sorts.`,
    tension: `Critics say no one actually suspends the world, and that descriptions smuggle theory under the name of purity. Naturalists ask why first-person reports should constrain third-person science. Phenomenologists reply that every experiment already presupposes a lifeworld of equipment and meaning. The method is most powerful as a discipline of attention, and most vulnerable when it claims exclusive jurisdiction over the mental.`,
  },
  "classical-mechanics": {
    lede: `[[classical-mechanics|Classical mechanics]] is the theory of the middle-scale world: laws of motion, forces, energy, and constraints, written by [[newton|Newton]] and rewritten by Lagrange and Hamilton. [[calculus|Calculus]] is its language; [[chaos-theory|chaos theory]] is the discovery that its determinism need not be predictable.`,
    idea: `Newton's laws plus gravity convert forces into trajectories. The Lagrangian replaces forces with stationary action; Hamilton's equations make phase space the natural arena and conservation laws the shadows of symmetries (Noether, 1918). Rigid bodies, continua, and celestial perturbation theory are specializations. The theory is deterministic in the Cauchy sense while solutions exist. Poincaré already knew many-body problems can be non-integrable; Lorenz showed that exponential sensitivity can make unique evolution unknowable in practice. [[relativity|Relativity]] and [[quantum-mechanics|quantum mechanics]] bound the kingdom rather than annexing it.`,
    lineage: `Galileo's kinematics, Descartes's quantity of motion, the Principia (1687), then Euler, d'Alembert, Lagrange, Hamilton, Jacobi. Engineering kept force diagrams; the late nineteenth century added qualitative dynamics. Continuum mechanics and nonlinear dynamics expanded the toolkit without abandoning definite trajectories. [[thermodynamics|Thermodynamics]] sits beside it as a constraint on which mechanical processes can occur.`,
    tension: `Laplace's demon needs infinite precision. Force as a primitive embarrasses those who want inertia explained by the world's mass distribution; general relativity dissolves gravitational force into geodesics. No one designs a bridge in Hilbert space. Correspondence, in [[bohr|Bohr]]'s hands, is a demand that old trajectories reappear in a limit, not a derivation of them.`,
  },
  "quantum-mechanics": {
    lede: `[[quantum-mechanics|Quantum mechanics]] is the theory of the very small, in which chance, superposition, and entanglement replace classical trajectories. The [[wave-function|wave function]] is the state; the [[uncertainty-principle|uncertainty principle]] is a limit; [[bohr|Bohr]] and [[feynman|Feynman]] are two of its dialects.`,
    idea: `A closed system's state is a Hilbert-space vector evolving unitarily. Observables are operators; outcomes are eigenvalues with Born-rule probabilities. Non-commuting operators cannot be assigned simultaneous definite values. Entanglement means a composite can have a definite state when its parts do not. Bell (1964) and later experiments ruled out local hidden variables of the classical kind. Quantum field theory extends the story to variable particle number and underpins the [[standard-model|Standard Model]]. [[quantum-computing|Quantum computing]] treats amplitudes as resources. Interpretation — Copenhagen, many-worlds, Bohm, collapse, QBism — is the unfinished metaphysics.`,
    lineage: `Planck 1900, Einstein 1905, Bohr 1913, de Broglie, Heisenberg, Schrödinger, Dirac, von Neumann. Solvay 1927 staged the Bohr–Einstein debate. QED, renormalized by Tomonaga, Schwinger, and Feynman, made the theory a precision machine. Decoherence explained classical appearance without, by itself, explaining unique outcomes. [[information-theory|Information theory]] is now a preferred idiom of several interpretations.`,
    tension: `Unitary evolution is linear and reversible; definite outcomes are not. That is the measurement problem. Each interpretation pays a price: ontology, nonlocality, new constants, or a refusal to finish the theory. Until a price is accepted, QM remains the most accurate algorithm whose subject matter is still in court.`,
  },
  relativity: {
    lede: `[[relativity|Relativity]] is Einstein's reconstruction of space, time, and gravity as geometry in motion. [[spacetime|Spacetime]] replaces the Newtonian stage; [[black-holes|black holes]] and [[cosmology|cosmology]] are what the geometry permits when it is left to curve.`,
    idea: `Special relativity (1905) makes the speed of light invariant and simultaneity frame-dependent. Minkowski geometry unifies the two remaining invariants: the interval, and cause preceding effect inside a light cone. General relativity (1915) lets spacetime curve in response to stress-energy; free fall is geodesic motion; Newton's gravity is the small-field, low-speed remainder. GPS, gravitational lensing, gravitational waves, and the precession of Mercury are not illustrations. They are the theory happening. [[einstein|Einstein]] spent later years hunting a unification that did not arrive.`,
    lineage: `Maxwell's electromagnetism already picked a speed. Michelson–Morley failed to find the ether wind. Lorentz transformations waited for an interpretation; Einstein supplied it by discarding absolute time. Grossmann helped with the tensor calculus; Hilbert raced the field equations; Schwarzschild found the first exact solution that would become a black hole.`,
    tension: `Quantum theory and GR still do not share a formalism. Singularities look like the theory announcing its own limit. The block universe implied by the geometry offends those who want a genuine present. The atlas files that offense under [[metaphysics|metaphysics]] and keeps the geometry.`,
  },
  thermodynamics: {
    lede: `[[thermodynamics|Thermodynamics]] is the science of heat, work, and the arrow of time written in [[entropy|entropy]]. It is the constraint on engines, on life, and on any story about why cups cool.`,
    idea: `Energy is conserved (first law). Entropy of an isolated system does not decrease (second). There is a zero of temperature (third) and an absolute scale (zeroth). Statistical mechanics, after Maxwell, Boltzmann, and Gibbs, explains the laws as overwhelmingly probable behavior of many particles. Entropy then looks like missing information, which is why this node shares an edge with [[information-theory|information theory]]. Life, as Schrödinger noted, feeds on negative entropy; [[origin-of-life|origin of life]] and [[complexity|complexity]] are downstream arguments.`,
    lineage: `Carnot's engine, Clausius's entropy, Kelvin's scales, Boltzmann's H-theorem and his tombstone formula, Gibbs's ensembles, Onsager's relations, Prigogine's far-from-equilibrium work. Engineering kept the steam tables; physics kept the arrow.`,
    tension: `Loschmidt's reversibility paradox and Poincaré recurrence still need a cosmological or typicality answer. Maxwell's demon is now an information-processing problem. Whether the thermodynamic arrow is the cosmological arrow is an open joint with [[cosmology|cosmology]].`,
  },
  "particle-physics": {
    lede: `[[particle-physics|Particle physics]] is the catalog of elementary particles and the forces that braid them. The [[standard-model|Standard Model]] is its masterpiece and its unfinished sentence.`,
    idea: `Quarks, leptons, gauge bosons, and the Higgs field: a quantum field theory with SU(3)×SU(2)×U(1) gauge symmetry, tested to absurd precision at accelerators. QCD confines color; electroweak theory unifies two forces and is spontaneously broken by the Higgs mechanism. Neutrino masses and mixings already require an extension. Gravity is not in the model. [[feynman|Feynman]] diagrams are the bookkeeping of amplitudes. [[cosmology|Cosmology]] needs the early-universe thermal history this theory supplies — and then needs more, because [[dark-matter|dark matter]] is not in the catalog.`,
    lineage: `Cathode rays, Rutherford, cosmic-ray muons and pions, the particle zoo of the 1950s–60s, Gell-Mann's quarks, Glashow–Weinberg–Salam, QCD, the W and Z, the top quark, the Higgs in 2012. Each was a bet that the zoo had a taxonomy.`,
    tension: `Hierarchy, strong CP, baryon asymmetry, dark matter, and quantum gravity are not details. They are the reasons the Standard Model is called a model. Unification schemes proliferate; data has been stingy since the Higgs.`,
  },
  cosmology: {
    lede: `[[cosmology|Cosmology]] is the study of the universe as a whole — its beginning, contents, and fate. [[relativity|Relativity]] supplies the geometry; [[particle-physics|particle physics]] supplies the early recipe; [[dark-matter|dark matter]] and dark energy supply most of the budget and none of the names.`,
    idea: `An expanding FLRW spacetime, a hot Big Bang, light elements from nucleosynthesis, a cosmic microwave background, structure grown from tiny fluctuations, accelerated expansion. Inflation is the leading story about the fluctuations and the horizon. Black holes are local endpoints; the heat death is a global rumor written in [[entropy|entropy]]. Observations — supernovae, baryon acoustic oscillations, CMB anisotropies, large-scale surveys — turned cosmology into a precision science without turning it into a finished one.`,
    lineage: `Einstein's static universe, Friedmann's expanding solutions, Lemaître, Hubble's redshift-distance relation, Penzias and Wilson's hiss, COBE, WMAP, Planck. The dark sector arrived as a pair of accounting crises.`,
    tension: `The Hubble tension, the nature of dark energy, the measure problem in inflation, and the still-missing quantum origin of spacetime are research programs, not homework. A map of the universe is still a map with dragons.`,
  },
  newton: {
    lede: `[[newton|Isaac Newton]] (1643–1727) wrote the laws of [[classical-mechanics|classical mechanics]], invented a mathematics of fluxions alongside Leibniz, and made light a subject of experiment. The [[scientific-revolution|Scientific Revolution]] is unthinkable without the Principia.`,
    idea: `Three laws and universal gravitation. The world as particles in absolute space and time, acting at a distance with a force that falls as the square. Optics by prism and hypothesis non fingo — except when he fingo'd plenty. Alchemy and chronology occupied him as seriously as gravity, a fact later textbooks found inconvenient. [[calculus|Calculus]] as fluxions was a tool for the physics; the priority dispute with Leibniz was a tool for the reputation.`,
    lineage: `Woolsthorpe, Cambridge, the plague years, the Royal Society, the Mint. Influence is not a word; it is the default operating system of physical science until Einstein.`,
    tension: `Action at a distance embarrassed Newton himself. Absolute space was a theological as well as a physical commitment. The man was vengeful. The theory was generous.`,
  },
  einstein: {
    lede: `[[einstein|Albert Einstein]] (1879–1955) bent [[spacetime|spacetime]] and opened the quantum door with the photon. [[relativity|Relativity]] is his monument; his unease with [[quantum-mechanics|quantum mechanics]] is his unfinished argument.`,
    idea: `1905: light quanta, Brownian motion as evidence of atoms, special relativity. 1915: general relativity. Later: Bose–Einstein statistics, the EPR paper as a weapon against incompleteness, a hunt for unification that isolated him from the quantum generation. He was not a mystic. He was a realist who thought the world's laws should not play dice — a slogan that hid a precise complaint about the [[wave-function|wave function]].`,
    lineage: `Patent office, Bern, Prague, Berlin, Princeton. The century's physics is in large part a set of footnotes to those years, including the ones he lost.`,
    tension: `The dice are still rolling. Unification is still a wish. The public Einstein is a saint; the historical one is a patent clerk with a ruthless taste for principles.`,
  },
  bohr: {
    lede: `[[bohr|Niels Bohr]] (1885–1962) built the old quantum atom, named complementarity, and became the pastor of the Copenhagen reading of [[quantum-mechanics|quantum mechanics]].`,
    idea: `The 1913 atom quantized angular momentum and explained spectral lines as jumps. Correspondence demanded that classical results reappear in the right limit. Complementarity said that wave and particle, spacetime and causal descriptions, are mutually exclusive and jointly necessary. The Bohr–Einstein debates are still the template for talking about measurement. He was less a formalist than a philosopher of what can be said.`,
    lineage: `Copenhagen as a place and as a school. Students and visitors — Heisenberg, Pauli, Dirac, Gamow — carried the dialect. After the war he worked for openness about nuclear arms, a political complementarity.`,
    tension: `Copenhagen is accused of being an instrumentalism with a priesthood. Bohr's prose is famously difficult; his physics was not. Whether complementarity is a deep insight or a refusal to finish the theory is the live question.`,
  },
  feynman: {
    lede: `[[feynman|Richard Feynman]] (1918–1988) made quantum electrodynamics a set of diagrams, path integrals a method, and explanation a public craft. [[particle-physics|Particle physics]] still sketches in his lines.`,
    idea: `Sum over histories: the amplitude to go from A to B is a coherent sum over every path, including the absurd ones, with the classical path dominating by stationary phase. Feynman diagrams turn ugly integrals into pictures of vertices and propagators. The parton picture, the weak-interaction work, the lectures, the Challenger O-ring: a style in which the shortest true sentence is the one that counts. He also helped start the conversation that became nanotechnology and gestured at [[computation-theory|computation]] with quantum systems.`,
    lineage: `Far Rockaway, MIT, Princeton (Wheeler), Los Alamos, Cornell, Caltech. QED's renormalization was a three-way credit with Schwinger and Tomonaga; the diagrams made his version the one people could teach.`,
    tension: `The showman can hide the unfinished. Path integrals are still trickier to make rigorous than they look on a blackboard. The style invites imitation; the results do not.`,
  },
  maxwell: {
    lede: `[[maxwell|James Clerk Maxwell]] (1831–1879) unified electricity, magnetism, and light into a single field theory. [[electromagnetism|Electromagnetism]] is his continent; statistical physics and color vision were side rooms.`,
    idea: `Four equations (in Heaviside's later vector form) and a current that had to be there for consistency: the displacement current. Light became an electromagnetic wave with a predicted speed matching experiment. The field ceased to be a bookkeeping device and became the thing. Kinetic theory and the Maxwell–Boltzmann distribution opened [[thermodynamics|thermodynamics]] to particles. The demon thought-experiment still feeds [[information-theory|information theory]].`,
    lineage: `Edinburgh, Cambridge, King's College, the Cavendish. Faraday's lines of force were the intuition; Maxwell's mathematics made them a theory. Einstein said he stood on Maxwell's shoulders when he discarded the ether but kept the field.`,
    tension: `The ether Maxwell believed in did not survive 1905. The equations did. That is a lesson about theories: the furniture can go, the relations remain.`,
  },
  entropy: {
    lede: `[[entropy|Entropy]] is the measure of missing information, the tally of ways a system can be, the reason cups cool. It is the hinge between [[thermodynamics|thermodynamics]], [[information-theory|information theory]], and [[complexity|complexity]].`,
    idea: `Clausius's dQ/T became Boltzmann's k log W. Shannon's H is the same shape for a communication source. The physical and the informational readings are cousins, not identities, and the family fights are productive: Maxwell's demon, Landauer's principle, black-hole entropy and the holographic rumor. [[origin-of-life|Life]] locally decreases entropy by exporting it. The arrow of time is, in one leading story, the fact that we are downstream of a low-entropy past.`,
    lineage: `Steam engines, then statistical mechanics, then communication engineering, then Wheeler's "it from bit," then the quantum-information recasting of many-body physics.`,
    tension: `Which entropy, whose coarse-graining, which past hypothesis? Until those are specified, "entropy increases" is a slogan. Specified, it is the deepest cheap sentence in science.`,
  },
  spacetime: {
    lede: `[[spacetime|Spacetime]] is the four-dimensional arena in which events have no absolute when or where, only interval. [[relativity|Relativity]] made it; [[black-holes|black holes]] puncture it; [[metaphysics|metaphysics]] still argues about whether it is a substance.`,
    idea: `Minkowski space for special relativity; a Lorentzian manifold for general relativity, curved by stress-energy. Light cones police causation. Coordinates are labels, not the thing. The thing is the metric and the events. Relationalists want to dissolve the arena into relations among matter; substantivalists want it to exist even when empty. Hole arguments and diffeomorphism invariance are the technical form of that fight.`,
    lineage: `Newton's absolute space, Leibniz's relations, Euler's and Kant's uses of incongruent counterparts, then Einstein and Minkowski. Field theory made the arena dynamical.`,
    tension: `Does spacetime emerge from something more like entanglement or information? Quantum gravity research programs bet yes in different dialects. Until one pays off, spacetime is both the best map we have and, perhaps, a large-scale appearance.`,
  },
  "uncertainty-principle": {
    lede: `The [[uncertainty-principle|uncertainty principle]] is the built-in trade-off between knowing a particle's position and its momentum. It is not a clumsiness of instruments. It is a fact about the [[wave-function|wave function]] and the operators of [[quantum-mechanics|quantum mechanics]].`,
    idea: `Heisenberg's 1927 intuition, Kennard's inequality, Robertson's general form: the product of standard deviations of non-commuting observables has a positive lower bound. A narrow wave packet in x is wide in p. The principle licenses qualitative reasoning about ground-state energies, tunneling, and why atoms have size. Information-theoretic recastings talk about the limits of jointly encoding conjugate questions. [[epistemology|Epistemology]] sometimes borrows it as a metaphor, usually badly.`,
    lineage: `Heisenberg's microscope thought-experiment, Bohr's complementarity as a philosophical upgrade, then rigorous inequalities and, later, entropic versions. It became the public face of quantum weirdness, for better and worse.`,
    tension: `Measurement disturbance versus ontic indeterminacy: does the principle say what we can know, or what is not there? The formalism is happier with the latter; talk is happier with the former. Experiments with weak values and error-disturbance relations keep the distinction live.`,
  },
  "black-holes": {
    lede: `[[black-holes|Black holes]] are regions where [[spacetime|spacetime]] curves past the point of return. They are solutions, observations, and a crisis for information.`,
    idea: `An event horizon hides a singularity (or whatever quantum gravity puts there). The Schwarzschild, Kerr, and Reissner–Nordström families are the textbook inventory. Hawking radiation assigns them temperature and [[entropy|entropy]] (Bekenstein–Hawking), which makes them thermodynamic objects and threatens unitarity if information cannot get out. LIGO hears mergers; EHT photographs shadows. They are no longer only theory.`,
    lineage: `Schwarzschild 1916, Oppenheimer–Snyder collapse, Wheeler's name, Penrose's singularity theorem, Carter–Hawking–Ellis uniqueness folklore, Hawking 1974, LIGO 2015.`,
    tension: `The information paradox is the sharpest joint between [[relativity|relativity]] and [[quantum-mechanics|quantum mechanics]]. Firewalls, complementarity, holography, and replicas are research programs, not answers. The atlas files the paradox on the edge with [[information-theory|information theory]].`,
  },
  "wave-function": {
    lede: `The [[wave-function|wave function]] is the complete quantum state: a map of amplitudes whose squared modulus yields chance. It is the noun of [[quantum-mechanics|quantum mechanics]] and the subject of its religious wars.`,
    idea: `Ψ(x,t) in the Schrödinger picture; a vector in Hilbert space in the abstract; a functional of fields in QFT. The Born rule converts amplitude to probability. Interference is the fact that amplitudes add and probabilities do not. Collapse, branching, or Bayesian update — depending on church — happens on measurement. [[uncertainty-principle|Uncertainty]] is a theorem about this object. [[information-theory|Information]] interpretations treat it as a catalog of beliefs; psi-ontic views treat it as a physical field.`,
    lineage: `Schrödinger 1926, Born's probability, Dirac's transformation theory, von Neumann's projection, decoherence, the PBR theorem as a constraint on psi-epistemic models.`,
    tension: `What is it? A wave in 3N-dimensional configuration space is an odd inhabitant of a 3D world. That oddity drives many-worlds, hidden variables, and "just shut up and calculate." The atlas will not calculate for you.`,
  },
  "standard-model": {
    lede: `The [[standard-model|Standard Model]] is the most precise theory humans have of the non-gravitational forces, and it is still incomplete. [[particle-physics|Particle physics]] is largely the story of building it and then staring at its gaps.`,
    idea: `A renormalizable quantum field theory of quarks and leptons interacting via gluons, W and Z bosons, photons, with masses from the Higgs field. It predicted the charm quark, the Z width, the Higgs, and a thousand branching ratios. Neutrino masses already sit outside the original model. Gravity, dark matter, and the cosmological constant sit outside any friendly extension. Gauge symmetry is the aesthetic and the constraint.`,
    lineage: `Yang–Mills, Glashow, Weinberg, Salam, QCD's asymptotic freedom (Gross, Politzer, Wilczek), 't Hooft and Veltman's renormalizability, decades of collider confirmation.`,
    tension: `Naturalness expected superpartners around the corner. They did not come. Whether that kills naturalness or just the simplest models is a sociological as well as a physical question. [[dark-matter|Dark matter]] is the most embarrassing absence.`,
  },
  "dark-matter": {
    lede: `[[dark-matter|Dark matter]] is the unseen mass that sculpts galaxies and refuses, so far, to show up in detectors. [[cosmology|Cosmology]] needs it; the [[standard-model|Standard Model]] does not contain it.`,
    idea: `Galaxy rotation curves, gravitational lensing, CMB peaks, and simulation of structure formation all want a gravitationally interacting, weakly luminous component amounting to about five times the baryons. WIMPs, axions, sterile neutrinos, and primordial black holes are candidates. Direct detection, indirect detection, and collider searches have produced constraints, not discoveries. Modified gravity (MOND and heirs) tries to do without it and then struggles with the CMB and clusters.`,
    lineage: `Zwicky's missing mass in the Coma cluster, Rubin's rotation curves, the 1980s particle-physics coincidence of WIMP relic density, then a long experimental campaign.`,
    tension: `A theory that explains everything except what most of the universe is made of is a theory with a hole in the middle. The hole is this node.`,
  },
  electromagnetism: {
    lede: `[[electromagnetism|Electromagnetism]] is one force with two faces, carrying light, chemistry, and almost every machine. [[maxwell|Maxwell]] wrote it down; [[relativity|relativity]] made its speed a law of spacetime; [[particle-physics|particle physics]] made it a gauge theory.`,
    idea: `Charges produce fields; changing fields produce fields; light is the free field. The Lorentz force tells matter how to listen. In quantum dress it is QED, the most precisely tested piece of the [[standard-model|Standard Model]]. Chemistry is applied electromagnetism in potential wells; [[photosynthesis|photosynthesis]] is applied electromagnetism in a leaf. Radio to gamma are one spectrum.`,
    lineage: `Coulomb, Ørsted, Ampère, Faraday, Maxwell, Hertz, then Einstein's special relativity as a theory of this force's symmetry. Quantum electrodynamics completed the microscopic story.`,
    tension: `The magnetic monopole has not been found. The fine-structure constant is a number with no accepted derivation. Unification with the weak force is accomplished; with the others, not.`,
  },
};
